export function renderSquarePensMissing(w){
 const m=missingSquareModel(w);if(!m)return '';

 return `<section class="sp-missing" data-sp-missing-step="${m.step}"><p class="sp-waiting">${esc(missingSquareCopy.buildKept)}</p><h2 id="sp-task" tabindex="-1">${esc(missingSquareCopy.title)}</h2><nav class="sp-missing-steps" aria-label="Choose a missing-side step">${missingSquareCopy.steps.map((label,i)=>button(`missing-step-${i}`,label,false,`aria-current="${m.step===i?'step':'false'}"`)).join('')}</nav><p class="sp-lesson">${esc(missingSquareCopy.prompts[m.step])}</p><div class="sp-actions sp-missing-tools">${button('missing-turn',missingSquareCopy.turn)}${button('missing-another',missingSquareCopy.another)}</div><div class="sp-missing-workbench"><div><div class="sp-missing-areas${m.step===2?' sp-missing-areas-pair':''}">${missingAreaPicture(m)}${m.step===2?missingAreaPicture(m,true):''}</div><p>Long-side square: ${m.c} × ${m.c} = ${squareUnits(m.C)}.</p><p>Known short-side square: ${m.a} × ${m.a} = ${squareUnits(m.A)}.</p>${m.step>=1?`<p data-sp-missing-difference>Other square’s area: ${m.C} − ${m.A} = ${squareUnits(m.N)}.</p><p>${esc(missingSquareCopy.lShape)}</p><p class="sp-equation">b² = c² − a²</p>`:''}</div>${missingTriangle(m)}</div>${m.step===2?`<section class="sp-missing-answer" data-sp-missing-answer><h3>The missing short side</h3>${m.exact?`<p>${m.k} × ${m.k} = ${m.N}, so the missing short side is ${units(m.k)}. ${esc(missingSquareCopy.positive)}</p>`:`<p>${m.k} × ${m.k} = ${m.K}; ${m.u} × ${m.u} = ${m.U}. ${m.N} lies between ${m.K} and ${m.U}. The missing short side is between ${m.k} and ${m.u} units. Its exact name is √${m.N} units.</p><p>The positive number whose square is ${m.N}.</p>`}<p>The long side ${units(m.c)} is longer than either short side.</p><p>${esc(missingSquareCopy.contrast)}</p></section>`:''}${m.step<2?'<p>Before you reveal the next step, tell someone what you think.</p>':''}<div class="sp-actions">${button('missing-previous','Previous step',m.step===0)}${button('missing-next','Next step',m.step===2)}${button('build','Back to my pieces')}</div></section>`;
}
const gridSteps=acrossPlanCopy.steps;
function gridControls(w){const point=w.gridPoint,x=w[`grid${point}x`],y=w[`grid${point}y`];return `<section class="sp-grid-controls" data-sp-grid-controls aria-label="Paper plan positions"><div class="sp-grid-coordinates"><p>A: (${w.gridAx}, ${w.gridAy})</p><p>B: (${w.gridBx}, ${w.gridBy})</p></div><div class="sp-actions" role="group" aria-label="Choose a point">${['A','B'].map(p=>button(`gp-${p}`,`Move ${p}`,false,`aria-pressed="${point===p}"`)).join('')}</div><div class="sp-grid-coordinate-tools">${[['x','x across',x],['y','y up',y]].map(([axis,label,value])=>`<fieldset><legend>${label}</legend><div>${button(`g${axis}-less`,'Less',value===0,`aria-label="Point ${point}, ${label}: less"`)}<output aria-label="Point ${point}, ${label}">${value}</output>${button(`g${axis}-more`,'More',value===12,`aria-label="Point ${point}, ${label}: more"`)}</div></fieldset>`).join('')}</div></section>`;}
function gridStepChoices(w){return `<nav class="sp-grid-steps" aria-label="Choose a paper plan step">${gridSteps.map((label,i)=>button(`grid-step-${i}`,label,false,`aria-current="${w.gridStep===i?'step':'false'}"`)).join('')}</nav>`;}
function gridPicture(m){
 const map=([x,y])=>[50+x*24,338-y*24],line=(a,b,extra='')=>{const p=map(a),q=map(b);return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" ${extra}/>`;};
 const grid=Array.from({length:13},(_,i)=>`${line([i,0],[i,12])}${line([0,i],[12,i])}`).join('');
 const mark=m.kind==='triangle'?(()=>{const [x,y]=m.E,s=Math.min(.3*Math.min(m.h,m.v),.6),dx=m.A[0]===x?Math.sign(m.B[0]-x):Math.sign(m.A[0]-x),dy=m.A[1]===y?Math.sign(m.B[1]-y):Math.sign(m.A[1]-y);return `<polyline data-sp-grid-right-corner points="${pts([[x+dx*s,y],[x+dx*s,y+dy*s],[x,y+dy*s]],map)}" class="sp-grid-corner"/>`;})():'';
 const point=(p,label,offset)=>{const [x,y]=map(p);return `<circle cx="${x}" cy="${y}" r="5" class="sp-grid-dot"/><text x="${x+offset}" y="${y-12}" text-anchor="${offset<0?'end':'start'}">${label}</text>`;};
 return `<figure class="sp-grid-figure" data-sp-grid-figure><svg viewBox="0 0 388 410" role="img" aria-label="Paper plan. x runs across to the right and y runs up. ${m.kind==='same'?'A and B share one position.':m.kind==='axis'?'The straight segment and edge route overlap on one grid line.':'An edge route turns at a square corner. A separate dashed straight segment joins A to B.'}"><g class="sp-grid-lines">${grid}</g><g class="sp-grid-axis-labels">${[0,6,12].map(i=>{const [x,y]=map([i,i]);return `<text x="${x}" y="367" text-anchor="middle">${i}</text><text x="31" y="${y+7}" text-anchor="end">${i}</text>`;}).join('')}<text x="194" y="399" text-anchor="middle">x across</text><text x="50" y="25">y up</text></g><g class="sp-grid-edge">${m.segments.map((segment,i)=>line(segment.from,segment.to,`data-sp-grid-interval="${i}" data-sp-grid-highlighted="${i<m.trace}" class="${i<m.trace?'sp-grid-prefix':''}"`)).join('')}</g>${m.kind==='same'?'':line(m.A,m.B,'class="sp-grid-straight"')}${mark}${m.kind==='same'?point(m.A,'A = B',m.ax>8?-12:12):point(m.A,'A',m.ax>m.bx?12:-12)+point(m.B,'B',m.bx>=m.ax?12:-12)}</svg><figcaption><span class="sp-grid-route-key">Following the grid edges</span><span class="sp-grid-straight-key">Straight segment</span></figcaption><p class="sp-grid-unit-key"><span aria-hidden="true"></span>${esc(acrossPlanCopy.unitKey)}</p>${m.kind==='axis'?'<p>The straight segment and edge route overlap here.</p>':m.kind==='same'?`<p>${esc(acrossPlanCopy.coincident)}</p>`:''}</figure>`;
}
function gridAreas(m){const size=156,scale=140/Math.max(m.h,m.v);return `<section class="sp-grid-areas" data-sp-grid-areas><h3>Compare the two known-side squares</h3><div class="sp-grid-square-pair">${[[m.h,m.H,'Horizontal-side'],[m.v,m.V,'Vertical-side']].map(([side,area,name])=>`<figure><svg viewBox="0 0 ${size} ${size}" role="img" aria-label="${name} square. Side ${units(side)}, area ${squareUnits(area)}. Both squares use the same drawing scale."><rect data-sp-square-side="${side}" data-sp-square-area="${area}" x="8" y="${148-side*scale}" width="${side*scale}" height="${side*scale}"/></svg><figcaption>${name} square</figcaption><p>${side} × ${side} = ${squareUnits(area)}</p></figure>`).join('')}</div><p>Long-side square: ${m.H} + ${m.V} = ${squareUnits(m.N)}.</p><p class="sp-equation">Distance² = ${m.N}</p><p>${m.N} is an area, not the distance. What positive length has that square?</p></section>`;}
function gridLength(m){return `<section class="sp-grid-length" data-sp-grid-length><h3>Find the straight distance</h3>${m.kind==='same'?'<p>The straight distance is 0 units. The edge route is also 0 units. Changing a point’s name does not move it.</p>':m.kind==='axis'?`<p>The straight distance is ${units(m.L)}. The edge route is also ${units(m.L)}: it already follows the straight grid line.</p>`:`${m.exact?`<p>${m.k} × ${m.k} = ${m.N}. The straight distance is ${units(m.k)}. We choose the positive length.</p>`:`<p>${m.k} × ${m.k} = ${m.K} and ${m.u} × ${m.u} = ${m.U}. ${m.N} lies between ${m.K} and ${m.U}. The straight distance is strictly between ${m.k} and ${units(m.u)}. Its exact name is √${m.N} units: the positive number whose square is ${m.N}.</p>`}<div class="sp-grid-distance" data-sp-grid-distance><p>Edge route: ${units(m.L)}</p><p>Straight distance: ${m.distance} units</p></div><p>${m.exact?`${m.k} is less than ${m.L}, so the straight segment is shorter.`:m.u===m.L?`The distance is less than ${units(m.u)}; the edge route is ${units(m.L)}.`:`The distance is less than ${units(m.u)}, and ${m.u} is less than ${m.L}, so the straight segment is shorter.`}</p><p>${esc(acrossPlanCopy.shorter)}</p>`}</section>`;}
export function renderSquarePensGrid(w){const m=gridDistanceModel(w);if(!m)return '';return `<section class="sp-grid" data-sp-grid data-sp-grid-kind="${m.kind}" data-sp-grid-step="${m.step}"><p class="sp-waiting">${esc(acrossPlanCopy.kept)}</p><h2 id="sp-task" tabindex="-1">${esc(gridSteps[m.step])}</h2>${gridStepChoices(w)}<div class="sp-grid-workbench">${gridPicture(m)}<div class="sp-grid-tools">${gridControls(w)}<p>${esc(acrossPlanCopy.reminder)}</p><div class="sp-actions">${button('grid-other','Use the other corner',m.kind!=='triangle')}${button('grid-another','Try another plan')}</div></div></div><section class="sp-grid-changes"><p>Horizontal change: ${Math.max(m.ax,m.bx)} − ${Math.min(m.ax,m.bx)} = ${units(m.h)}.</p><p>Vertical change: ${Math.max(m.ay,m.by)} − ${Math.min(m.ay,m.by)} = ${units(m.v)}.</p><p>Edge route: ${m.h} + ${m.v} = ${units(m.L)}.</p></section>${m.step===0?`<section class="sp-grid-count"><p>${m.kind==='same'?'A and B are at the same position. There are zero intervals between them.':m.kind==='axis'?`These points share one grid line. Count the ${m.L} ${m.L===1?'interval':'intervals'} between them. There is no turn.`:'The edge route changes one direction at a time. Count the intervals, not the endpoint dots. Which connection looks shorter?'}</p>${m.kind==='triangle'?`<p>${esc(acrossPlanCopy.squareCorner)}</p>`:''}<p data-sp-grid-trace-count>${m.trace} of ${m.L} edge ${m.L===1?'interval':'intervals'} highlighted.${m.L===0?' There are no edge intervals between these positions.':''}</p><div class="sp-actions">${button('grid-trace-next','Trace next interval',m.trace===m.L)}${button('grid-trace-back','Trace back',m.trace===0)}${button('grid-trace-all','Show the whole edge route',m.trace===m.L)}</div></section>`:m.kind==='triangle'?`<p>${esc(acrossPlanCopy.squares)}</p>${gridAreas(m)}`:`<p>${m.kind==='axis'?'Only one direction changes. There is no two-leg right triangle here, so no square calculation is needed.':'There is no triangle here and no square calculation is needed.'}</p>`}${m.step===2?gridLength(m):'<p>Before you reveal another step, tell someone what you think.</p>'}<p>${esc(acrossPlanCopy.return)}</p>${m.kind==='triangle'?`<p>${esc(acrossPlanCopy.returnTriangle)}</p>`:''}<details class="sp-grid-adult"><summary>For grown-ups: about this paper model</summary><p>${esc(acrossPlanCopy.adult)}</p></details><div class="sp-actions">${button('build','Back to my pieces')}</div></section>`;}
export function squarePensPage(book,owner){const v=existing(book,owner);if(!v?.active)return '';const w=v.pending??v.request??v.work,ready=v.ready===v.work&&!v.pending&&!v.request;
 return `<section class="sp-page" data-square-pens-root><header><div class="sp-topbar">${button('return','Back to Copy Frame')}<span>Square Pens · paper models</span></div><h1 id="square-pens-title" tabindex="-1">${w.page==='grid'?esc(acrossPlanCopy.title):'Same pieces, different squares'}</h1><p>${w.page==='grid'?esc(acrossPlanCopy.intro):w.page==='missing'?esc(missingSquareCopy.intro):'Pip needs a paper plan for square pens by the library garden. Can the same pieces explain the long side?'}</p><p class="sp-model-note">${w.page==='grid'?esc(acrossPlanCopy.model):'This is a made-up paper model, not a building plan.'}</p></header>${w.page==='grid'?(!ready?gridControls(w)+gridStepChoices(w):''):w.page==='missing'?missingDimensions(w):!ready||w.page==='build'?dimensions(w):''}${!ready?`<section class="sp-refusal"><h2 id="sp-task" tabindex="-1">Your choices are still here</h2><p>${refusal}</p><div class="sp-actions">${button('retry','Retry view')}<a href="#notes">Grown-up notes</a>${button('return','Back to Copy Frame')}</div></section>`:`<nav class="sp-pages" aria-label="Paper model pages">${[['build','Build'],['why','Why it works'],['corner','A different corner'],['missing','Find a short side'],['grid','Across the plan']].map(([page,label])=>button(`page-${page}`,label,false,`aria-current="${w.page===page?'page':'false'}"`)).join('')}</nav>${w.page==='build'?`<div class="sp-actions sp-material-actions">${button('turn','Turn the plan')}${button('another','Try another pen')}</div>`:''}${w.page==='grid'?renderSquarePensGrid(w):w.page==='why'?why(w):w.page==='corner'?corner(w):w.page==='missing'?renderSquarePensMissing(w):build(w)}${v.saveNotice?`<p class="sp-notice">${esc(v.saveNotice)}</p>`:''}<footer><a href="#learn/math/equality">Open Equality Desk</a><p>Choose Curve Window there to explore square rules. Going to Equality Desk starts a fresh paper plan when you return. Back to Copy Frame keeps this plan during this visit.</p></footer>`}<p class="sp-status" role="status" aria-live="polite">${esc(v.notice)}</p></section>`;
}
function visible(node){if(!node?.isConnected||!node.getClientRects().length)return false;for(let p=node;p;p=p.parentElement){const css=getComputedStyle(p);if(p.hidden||p.inert||p.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(p.tagName==='DETAILS'&&!p.open&&p!==node&&!p.querySelector(':scope>summary')?.contains(node))return false;}return true;}
export function bindSquarePens(book,ctx){const owner=ctx.explorerId?.(),v=existing(book,owner),root=document.querySelector('[data-square-pens-root]');if(!v?.active||!root)return;v.unbind?.();v.bound=root;
 const work=v.work,pending=v.pending,request=v.request,stateBytes=bytes([work,pending,request]),controls=[root,...root.querySelectorAll('button,a,select,summary')],invalid=new Set(),chains=new Map();
 for(const node of controls){const chain=[];for(let n=node;n&&n!==document;n=n.parentNode)chain.push([n,n.parentNode]);chains.set(node,chain);}
 const audit=records=>{for(const record of records)for(const removed of record.removedNodes)for(const node of controls)if(removed===node||removed.contains?.(node))invalid.add(node);};
 const observer=new MutationObserver(audit);observer.observe(document.documentElement,{childList:true,subtree:true});
 let retired=false;
 const live=node=>{audit(observer.takeRecords());try{return !retired&& visit===v&&v.active&&v.bound===root&&v.work===work&&v.pending===pending&&v.request===request&&bytes([v.work,v.pending,v.request])===stateBytes&&ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true&&location.hash===route&&document.querySelector('[data-square-pens-root]')===root&&!invalid.has(root)&&!invalid.has(node)&&chains.get(node)?.every(([n,p])=>n.parentNode===p)&&root.contains(node)&&visible(node)&&!node.disabled;}catch{return false;}};
 const on=(node,type,fn,capture=false)=>{node.addEventListener(type,fn,capture);};
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 const redraw=(focus='#sp-task')=>{
  ctx.render?.();const nextRoot=document.querySelector('[data-square-pens-root]');let n=nextRoot?.querySelector(focus);
  if(n?.disabled){const action=n.dataset.spAction,other={move:'move-back','move-back':'move','reset-pieces':'move','why-next':'why-back','why-back':'why-next','a-less':'a-more','a-more':'a-less','b-less':'b-more','b-more':'b-less','mc-less':'mc-more','mc-more':'mc-less','ma-less':'ma-more','ma-more':'ma-less','missing-next':'missing-previous','missing-previous':'missing-next','gx-less':'gx-more','gx-more':'gx-less','gy-less':'gy-more','gy-more':'gy-less','grid-trace-next':'grid-trace-back','grid-trace-back':'grid-trace-next'}[action];n=other?nextRoot.querySelector(`[data-sp-action="${other}"]`):null;}
  if(!n||n.disabled||!visible(n))n=nextRoot?.querySelector('#sp-task')??nextRoot?.querySelector('#square-pens-title');
  if(n){n.focus({preventScroll:true});const box=n.getBoundingClientRect();if(n.id==='sp-task'&&nextRoot.querySelector('[data-sp-grid]'))n.scrollIntoView({block:'start'});else if(box.top<0||box.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}
 };
 const propose=(next,focus)=>{if(!next)return;v.request=next;v.pending=null;v.ready=null;redraw(focus);};
 for(const node of controls)on(node,'click',event=>{if(!live(node)){event.preventDefault();event.stopImmediatePropagation();}},true);
 root.querySelectorAll('[data-sp-action]').forEach(node=>on(node,'click',()=>{if(!live(node))return;const action=node.dataset.spAction,base=v.request??v.pending??v.work;stop();
  if(action==='return'){ctx.onReturn?.();return;}
  if(action==='retry'){if(base.page==='grid')v.notice='';v.request=clone(v.pending??v.work);v.pending=null;v.ready=null;redraw();return;}
  if(/^[ab]-(less|more)$/.test(action)){if(base.page==='missing'||base.page==='grid')return;const [key,dir]=action.split('-'),next=changeSquarePensDraft(base,{[key]:base[key]+(dir==='more'?1:-1)});v.notice='';propose(next,`[data-sp-action="${action}"]`);return;}
  if(/^m[ca]-(less|more)$/.test(action)){
   if(base.page!=='missing')return;const [id,dir]=action.split('-'),key=id==='mc'?'missingC':'missingA',next=changeSquarePensDraft(base,{[key]:base[key]+(dir==='more'?1:-1)});v.notice='';propose(next,`[data-sp-action="${action}"]`);return;
  }
  if(/^(gp-[AB]|g[xy]-(less|more)|grid-step-[012]|grid-(other|another|trace-next|trace-back|trace-all))$/.test(action)){
   if(base.page!=='grid')return;let patch=null,next=null;
   if(action.startsWith('gp-'))patch={gridPoint:action.at(-1)};
   else if(/^g[xy]-/.test(action)){const key=`grid${base.gridPoint}${action[1]}`;patch={[key]:base[key]+(action.endsWith('more')?1:-1)};}
   else if(action.startsWith('grid-step-'))patch={gridStep:Number(action.at(-1))};
   else if(v.ready&&!v.pending){const m=gridDistanceModel(base);if(action==='grid-other')patch={gridElbow:1-base.gridElbow};else if(action==='grid-another')next=nextGridDistanceInvitation(base);else if(action==='grid-trace-next')patch={gridTrace:base.gridTrace+1};else if(action==='grid-trace-back')patch={gridTrace:base.gridTrace-1};else if(action==='grid-trace-all')patch={gridTrace:m.L};}
   next=next??(patch?changeSquarePensDraft(base,patch):null);if(next){v.notice=action==='grid-another'?`New paper plan: A (${next.gridAx}, ${next.gridAy}), B (${next.gridBx}, ${next.gridBy}).`:'';propose(next,action.startsWith('grid-step-')?'#sp-task':`[data-sp-action="${action}"]`);}return;
  }
  if(!v.ready||v.pending)return;
  if(action.startsWith('missing-')){
   if(base.page!=='missing')return;let next;
   if(action==='missing-another'){next=nextMissingSquareInvitation(base);if(next)v.notice=`New triangle: long side ${units(next.missingC)}, known short side ${units(next.missingA)}.`;}
   else if(action==='missing-turn')next=changeSquarePensDraft(base,{missingTurn:(base.missingTurn+1)%4});
   else if(action==='missing-next'||action==='missing-previous')next=changeSquarePensDraft(base,{missingStep:base.missingStep+(action==='missing-next'?1:-1)});
   else if(/^missing-step-[012]$/.test(action))next=changeSquarePensDraft(base,{missingStep:Number(action.at(-1))});
   if(next){if(action!=='missing-another')v.notice='';propose(next,`[data-sp-action="${action}"]`);}return;
  }
  if(base.page==='missing'&&!['build','page-build','page-why','page-corner','page-missing','page-grid'].includes(action))return;
  if(base.page==='grid'&&!['build','page-build','page-why','page-corner','page-missing','page-grid'].includes(action))return;
  let patch=null;
  if(action==='turn')patch={turn:(base.turn+1)%4};
  else if(action==='another'){const next=nextSquarePensInvitation(base);v.notice=`New pen: short sides ${units(next.a)} and ${units(next.b)}.`;propose(next,'[data-sp-action="another"]');return;}
  else if(action==='move')patch={move:base.move+1};
  else if(action==='move-back')patch={move:base.move-1};
  else if(action==='reset-pieces')patch={move:0};
  else if(action==='compare')patch={compare:true};
  else if(action==='compare-close')patch={compare:false};
  else if(action==='length')patch={lengthOpen:!base.lengthOpen};
  else if(action==='build')patch={page:'build'};
  else if(action.startsWith('page-'))patch={page:action.slice(5)};
  else if(action.startsWith('side-'))patch={markedSide:action.slice(5)};
  else if(/^why-\d$/.test(action))patch={whyStep:Number(action.slice(4))};
  else if(action==='why-back')patch={whyStep:base.whyStep-1};
  else if(action==='why-next')patch={whyStep:base.whyStep+1};
  if(patch){v.notice='';propose(changeSquarePensDraft(base,patch),action==='page-grid'?'#sp-task':`[data-sp-action="${action}"]`);}
 }));
 v.unbind=()=>{retired=true;observer.disconnect();};
}
